#!/usr/bin/env python3
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1];ios=json.loads((r/'results/ios-settings-map.json').read_text());android=json.loads((r/'results/android-settings-map.json').read_text())
a={n['key']:n for s in android['screens'] for n in s['items'] if n['key']};ii={n['key']:dict(n,screen=s['id']) for s in ios['screens'] if s['variant']=='base' for n in s['items'] if n['key']}
pairs={
'capture_logs':'pref_capture_android_logs','popup_ignore':'popup','popup_ignore_notify':'pref_ad_blocked_alert','ad_block':'pref_ad_block','redirect_ad_block':'pref_redirect_ad_block','javascript_alert_block':'pref_js_alert_block','javascript_confirm_block':'pref_js_confirm_block','javascript_prompt_block':'pref_js_prompt_block','search_engine':'pref_key_search_engine','restore_tabs_dialog':'pref_browser_tabs_restore','restore_tabs_automatic':'pref_browser_tabs_restore','dont_override_user_agent':'pref_dont_override_user_agent','invalid_ssl_certificate':'pref_invalid_ssl_certificate_ignore_all_domains','browser_open_in_tab':'pref_browser_open_in_tab','private_tab_share':'pref_browser_open_in_tab_external','prompt_subtitles':'pref_prompt_subtitles','skip_video_already_playing_dialog':'pref_skip_video_playing_dialog','never_resume_video':'pref_key_cast_resume','route_through_phone':'pref_key_route_through_phone','enable_played_dialog':'pref_enable_played_dialog','prefer_app':'pref_prefer_tv_app','allow_wvcconnect':'pref_receiver_connection_request_action','ts_video_convert_always':'pref_convert_m3u8_always','skip_back_seconds':'pref_rewind','skip_forward_seconds':'pref_forward','prevent_screen_lock':'pref_key_wake_lock','open_playback_control':'pref_open_playback_control','disable_volume_buttons':'pref_disable_volume_buttons','reconnect_to_streaming_device':'pref_key_reconnect','disable_thumbnails':'pref_disable_thumbnails','chromecast_receiver_type':'pref_chromecast_receiver_type','use_old_videojs':'pref_videojs_version','ip_preference':'pref_ip_preference','download_wifi':'pref_download_wifi','in_app_mute':'pref_in_app_player_always_mute','in_app_brightness_gesture':'pref_in_app_player_gesture_brightness_via_swipe','in_app_volume_gesture':'pref_in_app_player_gesture_volume_via_swipe','in_app_skip_gesture':'pref_in_app_player_gesture_skip_via_swipe','in_app_skip_tap_gesture':'pref_in_app_player_gesture_playback_via_double_tap','dark_mode':'pref_key_dark_mode','disable_error_reporting':'pref_disable_error_reporting','video_domain_reporting':'pref_key_disable_video_domain_reporting','delete_analytics_data':'pref_delete_analytics_data','auto_video_list':'pref_enable_auto_video_list','hide_m3u8_no_audio':'pref_hide_m3u8_no_audio','shadow_override':'pref_enable_inject','inject_javascript':'pref_enable_inject','in_app_repeat':'pref_in_app_player_repeat_playlists_always'}
# The Android domain reporting dependent row is not necessarily present as a packaged control.
notes={
'popup_ignore_notify':'Related only: iOS notifies about blocked popups generally; Android row specifically names blocked ad popups.',
'restore_tabs_dialog':'iOS splits ask and automatic into toggles; Android combines ASK/ALWAYS/NEVER in one list. Defaults correspond to asking.',
'restore_tabs_automatic':'Same Android counterpart as restore_tabs_dialog; not a second independent Android feature.',
'private_tab_share':'iOS can send externally shared links/media to private tabs; Android packaged external-tab list offers NEW/CURRENT only.',
'invalid_ssl_certificate':'iOS presents Prompt/Ignore/Cancel. Android uses management actions plus an ignore-all toggle; not equivalent enums.',
'never_resume_video':'False means the never-ask toggle is off. Android ASK is related; false alone does not prove native resume policy.',
'prefer_app':'Both default to Prompt despite different stored values (iOS 0, Android 1).',
'allow_wvcconnect':'Both default to prompting; option labels/storage differ.',
'prevent_screen_lock':'iOS description concerns routing video through phone. Android wake/Wi-Fi lock is related, not the same OS behavior.',
'chromecast_receiver_type':'iOS has a valid default selector. Android XML false is outside its values; traced native fallback is DEFAULT/0.',
'ip_preference':'iOS preferIPv4 matches its values. Android XML prefer_ipv4 is outside its numbered values; effective fallback unresolved.',
'use_old_videojs':'iOS boolean compatibility switch versus Android three-choice list; Android effective fresh version unresolved.',
'dark_mode':'Both default to system. iOS 1=Light, 2=Dark; Android 1=Dark, 2=Light. Never copy stored numeric values between platforms.',
'delete_analytics_data':'iOS declares a false reset toggle; Android is an action. Native reset effect unverified.',
'in_app_repeat':'iOS repeats video; Android row repeats playlists. Related but different scope.',
'shadow_override':'Same label does not prove same implementation; iOS key shadow_override is a hint, not confirmation of exact native mechanism.',
'inject_javascript':'Unlinked Hidden pane. Visibility/access unverified; not a normal Root-linked setting.'}
comparisons=[]
for key,n in ii.items():
 ak=pairs.get(key);an=a.get(ak) if ak else None
 comparisons.append({'ios_key':key,'ios_title':n['title'],'ios_screen':n['screen'],'ios_default':n['default'],'ios_options':n['options'],'android_key':ak if an else None,'android_title':an['title'] if an else None,'android_default':an['default'] if an else None,'android_options':an['options'] if an else None,'classification':'related_packaged_control' if an else 'no_direct_packaged_control_matched','notes':notes.get(key,'Unmatched in this settings comparison does not prove absence from Android runtime dialogs or code.' if not an else 'Compare user-visible meaning; key/value equality is not required.'),'evidence':{'ios':n['evidence'],'android':an['evidence'] if an else None}})
matched={c['android_key'] for c in comparisons if c['android_key']}
result={'scope':'Semantic comparison of packaged settings declarations; differing versions and platform scope; not device-tested','ios_controls_compared':len(comparisons),'comparisons':comparisons,'android_unmatched_rows':[{'key':n['key'],'title':n['title'],'default':n['default'],'evidence':n['evidence']} for k,n in a.items() if k not in matched and n['kind'] not in ('submenu','status')]}
(r/'results/ios-android-settings-comparison.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
def fmt(d):
 if d is None:return 'No direct match'
 if d['source']=='not_applicable':return 'Action/status'
 if d['source']=='not_declared':return 'Unresolved'
 v=d.get('label',d['value']);return 'On' if v is True else 'Off' if v is False else str(v)
def cell(x):return str(x).replace('|','\\|').replace('\n',' ')
md=['# iPhone versus Android settings','','Compared: supplied iOS 3.5/build 0 IPA and Android 6.0.3 APK. These are different release lines. This compares packaged declarations, not current phone settings, feature quality, or verified runtime parity. iOS encrypted native code prevents checking overrides and hidden-pane access.','','## Confirmed declared default differences','','| Setting | iOS | Android |','|---|---|---|','| Block website ads | On | Off; premium-related listener |','| Download only on Wi-Fi | Off | On |','| Disable thumbnail extraction | Off (extraction not disabled) | On |','','Both declare popup blocking and ad-redirect blocking on, and JavaScript alert/confirm/prompt blocking off. Route-through-phone is Ask on both. Back/forward defaults are 30/15 seconds on both, but iOS offers fixed 5/15/30/60 choices while Android uses numeric text inputs. These statements concern the declared or traced fresh fallback, not current effective settings.','','## Additional iOS settings exposed in these resources','','- Private tabs: Face ID/Touch ID access gate off; private-tab restore inclusion on; prevention of private recent-media history on; opening externally shared items privately off. No corresponding biometric toggle was found in Android packaged preferences. This does not prove Android lacks every related privacy behavior.','- In-app renderer: Auto, AVPlayer or VLCKit; Auto default. Rotation: follow phone, match video, fixed landscape-right or portrait; match video default on iPhone. The packaged iPad variant omits the rotation row.','- Legacy Amazon Fire TV casting off and Accept AirPlay auto connect off. These are explicit iOS settings without directly matched Android rows.','- Download location prompt off and conversion of downloaded TS to HLS when casting on. No direct Android settings rows matched.','- Browser automatic mute on, swipe navigation on, auto-hide navigation bar on and pull-to-refresh on. No direct Android rows matched; platform defaults/other UI might still supply related behavior.','- Video-count badge, Video detection 1, advanced detection and long-press casting are on. The first two and long-press control have no direct matched Android settings row. Their labels do not establish exact native implementation.','- AdBlockLists supplies 26 individual toggles: EasyList, annoyance, antiadblock and WVC enabled; privacy and 21 language lists disabled. Android exposes a list manager rather than these 26 packaged settings rows; that manager was not exhaustively compared here.','','## Unlinked debug pane','','Hidden.plist is not linked from Root.plist. It contains 13 controls: on-screen console/log limits/severity, HLS.js override, player share menu, JavaScript injection, iframe redirect blocking, console-detection blocking, download-permission override and onboarding/rating/consent/reset flags. Their presence does not prove that ordinary users can open the pane or that every flag is active. Iframe redirect and console-detection toggles default off; injection defaults on.','','## Representation differences that matter','','- Dark mode: both default to system, but Light/Dark numeric values are reversed.','- iOS restore-tabs toggles correspond to Android restore policy choices; do not count each toggle as an extra capability.','- TV-app preference: Prompt on both, stored as different numeric strings.','- SSL handling: iOS Prompt/Ignore/Cancel versus Android certificate managers plus ignore-all control.','- Chromecast/IP selector defaults are internally consistent in iOS resources; Android has the two XML/option inconsistencies documented in SETTINGS_CODE_AUDIT.md.','- Web Receiver compatibility is a boolean in iOS and a list in Android; the Android effective default remains unresolved.','','## Full row-by-row crosswalk','','Every iPhone/base control, including list toggles and unlinked debug controls, appears below. No direct match means no corresponding packaged settings control was matched, not proven absence of the feature.','','| iOS pane / setting | iOS default | Related Android control | Android default | Notes |','|---|---|---|---|---|']
for c in comparisons:md.append('| '+' | '.join(map(cell,[c['ios_screen']+' / '+str(c['ios_title']),fmt(c['ios_default']),c['android_title'] or 'No direct match',fmt(c['android_default']),c['notes']]))+' |')
md+=['','## Android controls without a direct match in this crosswalk','','These include advanced tab limits/recovery, page dark-mode strategy, proxy operating/generation modes and buffer size, player buffer/cache and volume controls, IPTV parsing/update controls, scrobbling and playlist intro/outro settings. No matching iOS plist row is not proof that iOS lacks the underlying feature.','','| Android setting | Default |','|---|---|']
for n in result['android_unmatched_rows']:md.append('| '+cell(n['title'])+' | '+cell(fmt(n['default']))+' |')
md+=['','## Artifacts and reproduction','','Read IOS_SETTINGS.md for every option and stored value, and results/ios-settings-map.json for raw specifiers and evidence. Rebuild with scripts/map_ios_settings.py and scripts/compare_settings.py. No app settings or account state were changed.','']
(r/'docs/IOS_ANDROID_SETTINGS_COMPARISON.md').write_text('\n'.join(md))
print('Compared',len(comparisons),'iOS controls;',sum(bool(c['android_key']) for c in comparisons),'have a related Android row')
